package com.schooloss.fullnative.feature.sfh;
import android.os.Bundle;import android.view.*;import android.widget.*;import com.schooloss.fullnative.core.*;import org.json.*;
public final class SfhDetailActivity extends BaseActivity {
 private int id;private String type,endpoint;
 @Override protected void onCreate(Bundle b){super.onCreate(b);id=getIntent().getIntExtra("id",0);type=getIntent().getStringExtra("type");if("sfh_lesson".equals(type))endpoint="sfh_lesson";else if("sfh_material".equals(type))endpoint="sfh_material";else if("sfh_assignment".equals(type))endpoint="sfh_assignment";else endpoint="sfh_submission";loading("Opening Study From Home","Loading native learning detail…");load();}
 private void load(){io.execute(()->{try{JSONObject r=api.get(endpoint,"id="+id);JSONObject d=r.optJSONObject("data");runOnUiThread(()->render(d));}catch(Exception e){runOnUiThread(()->error("Could not open Study From Home",e,this::load));}});}
 private void render(JSONObject d){LinearLayout p=Ui.v(this);p.setPadding(Ui.dp(this,14),Ui.dp(this,12),Ui.dp(this,14),Ui.dp(this,24));p.setBackgroundColor(Constants.BG);TextView back=Ui.text(this,"‹  Study From Home",12,Constants.BLUE,true);back.setOnClickListener(v->finish());p.addView(back);String title=d==null?Ui.pretty(type):d.optString("title",d.optString("assignment_title",d.optString("student_name",Ui.pretty(type))));p.addView(Ui.text(this,title,23,Constants.TEXT,true));if(d!=null){String[] keys={"topic","description","teacher_instructions","subject","class_name","section_name","status","due_at","display_status","feedback_summary","strengths","improvement_areas","correction_instructions"};for(String k:keys){String v=d.optString(k,"");if(v.isEmpty())continue;com.google.android.material.card.MaterialCardView c=Ui.card(this);LinearLayout in=Ui.v(this);in.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,10));in.addView(Ui.text(this,Ui.pretty(k),9,Constants.MUTED,true));in.addView(Ui.text(this,v,12,Constants.TEXT,false));c.addView(in);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.topMargin=Ui.dp(this,7);p.addView(c,lp);}}ScrollView s=new ScrollView(this);s.addView(p);setContentView(s);}
}